package ocean.ui;
import ocean.model.*;import ocean.service.*;import javax.swing.*;import javax.swing.border.*;import java.awt.*;import java.time.*;import java.util.*;import java.sql.SQLException;
/** Main Swing shell; CardLayout provides simple, reliable screen transitions. */
public class UserInterface {
 private final MessageService messages;private final BottleService bottles;private final FutureLetterService letters;private final StatisticsService stats;private final AccountService accounts;private LocalUser currentUser;private final JFrame frame=new JFrame("Message in a Bottle — The Digital Ocean");private final OceanPanel root=new OceanPanel();private final CardLayout cards=new CardLayout();private final JPanel pages=new JPanel(cards);private final Set<String> seen=new HashSet<>();private String discoveryCategory;
 public UserInterface(MessageService m,BottleService b,FutureLetterService f,StatisticsService s,AccountService a){messages=m;bottles=b;letters=f;stats=s;accounts=a;root.setLayout(new BorderLayout());pages.setOpaque(false);root.add(pages);frame.setContentPane(root);frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);frame.setMinimumSize(new Dimension(900,650));frame.setSize(1120,780);frame.setLocationRelativeTo(null);}
 public void show(){loginPage();frame.setVisible(true);}
 private JPanel page(String title,String sub){JPanel p=new JPanel(new GridBagLayout());p.setOpaque(false);GridBagConstraints c=new GridBagConstraints();c.gridx=0;c.gridy=0;c.insets=new Insets(8,20,8,20);c.fill=GridBagConstraints.HORIZONTAL;c.weightx=1;c.anchor=GridBagConstraints.CENTER;JPanel content=new JPanel();content.setOpaque(false);content.setLayout(new BoxLayout(content,BoxLayout.Y_AXIS));content.add(Theme.label(title,32,Theme.WHITE,true));if(sub!=null){content.add(Box.createVerticalStrut(8));content.add(Theme.label(sub,15,Theme.MUTED,false));}p.add(content,c);p.putClientProperty("content",content);return p;}
 private JPanel content(JPanel p){return (JPanel)p.getClientProperty("content");}
 private void loginPage(){JPanel p=page("A quieter place for your words","Sign in or create a local account to keep future letters private.");JPanel c=content(p);c.add(Box.createVerticalStrut(30));JPanel card=Theme.card();card.setLayout(new BoxLayout(card,BoxLayout.Y_AXIS));card.setMaximumSize(new Dimension(440,330));JLabel mark=Theme.label("◈",48,Theme.AQUA,true);mark.setAlignmentX(Component.CENTER_ALIGNMENT);card.add(mark);card.add(Box.createVerticalStrut(12));JTextField username=new JTextField();username.setFont(Theme.BODY);username.setBorder(new CompoundBorder(new LineBorder(new Color(190,220,235),1,true),new EmptyBorder(12,14,12,14)));JPasswordField password=new JPasswordField();password.setFont(Theme.BODY);password.setBorder(new CompoundBorder(new LineBorder(new Color(190,220,235),1,true),new EmptyBorder(12,14,12,14)));card.add(Theme.label("Username",13,Theme.MUTED,false));card.add(Box.createVerticalStrut(5));card.add(username);card.add(Box.createVerticalStrut(12));card.add(Theme.label("Password",13,Theme.MUTED,false));card.add(Box.createVerticalStrut(5));card.add(password);card.add(Box.createVerticalStrut(18));JPanel actions=new JPanel(new GridLayout(1,2,10,0));actions.setOpaque(false);JButton signIn=Theme.button("Sign in",true),create=Theme.button("Create account",false);actions.add(signIn);actions.add(create);card.add(actions);c.add(card);c.add(Box.createVerticalStrut(18));JLabel note=Theme.label("Your public bottles stay anonymous. Only future letters are saved to your account.",13,Theme.MUTED,false);note.setAlignmentX(Component.CENTER_ALIGNMENT);c.add(note);signIn.addActionListener(e->{try{Optional<LocalUser> u=accounts.login(username.getText(),password.getPassword());if(u.isEmpty()){JOptionPane.showMessageDialog(frame,"Username or password not recognized.","Sign in",JOptionPane.INFORMATION_MESSAGE);}else{currentUser=u.get();home();}}catch(Exception ex){error(ex);}});create.addActionListener(e->{try{currentUser=accounts.register(username.getText(),password.getPassword());home();}catch(Exception ex){error(ex);}});nav("login",p);}
 private void nav(String name,JPanel p){pages.add(p,name);cards.show(pages,name);}
 private void back(JPanel c){c.add(Box.createVerticalStrut(16));JButton b=Theme.button("←  Back to ocean",false);b.addActionListener(e->home());c.add(b);}
 private void home(){JPanel p=page("Message in a Bottle","Some words are meant to float, not to be sent.  ·  Signed in as "+currentUser.getUsername());JPanel c=content(p);c.add(Box.createVerticalStrut(45));JPanel buttons=new JPanel(new GridLayout(3,1,0,15));buttons.setOpaque(false);buttons.setMaximumSize(new Dimension(330,180));JButton write=Theme.button("✎   Write a Message",true),discover=Theme.button("◉   Discover a Bottle",false),future=Theme.button("✧   My Future Messages",false);buttons.add(write);buttons.add(discover);buttons.add(future);write.addActionListener(e->writePage());discover.addActionListener(e->discover());future.addActionListener(e->futurePage());c.add(buttons);c.add(Box.createVerticalStrut(28));JPanel extras=new JPanel(new FlowLayout(FlowLayout.CENTER,18,0));extras.setOpaque(false);JButton st=Theme.button("Ocean statistics",false),about=Theme.button("About",false),threads=Theme.button("Threads & deadlock",false),logout=Theme.button("Sign out",false);extras.add(st);extras.add(about);extras.add(threads);extras.add(logout);st.addActionListener(e->statistics());about.addActionListener(e->about());threads.addActionListener(e->threadDemo());logout.addActionListener(e->{currentUser=null;loginPage();});c.add(extras);c.add(Box.createVerticalStrut(35));c.add(Theme.label("A quiet place for words without an address.",14,Theme.MUTED,false));nav("home",p);}
 private void threadDemo(){JPanel p=page("Threads & deadlock","A short Java concurrency example for learning.");JPanel c=content(p);c.add(Box.createVerticalStrut(16));JTextArea explanation=new JTextArea("Two worker threads each add 1,000 to one shared counter. The synchronized method protects the shared value from simultaneous updates.\n\nDeadlock can happen when Thread A holds Lock 1 and waits for Lock 2, while Thread B holds Lock 2 and waits for Lock 1. This demo avoids that by always taking Lock 1 before Lock 2.");explanation.setWrapStyleWord(true);explanation.setLineWrap(true);explanation.setEditable(false);explanation.setOpaque(false);explanation.setForeground(Theme.WHITE);explanation.setFont(Theme.BODY);explanation.setMaximumSize(new Dimension(650,120));c.add(explanation);c.add(Box.createVerticalStrut(14));JTextArea output=new JTextArea(7,55);output.setEditable(false);output.setFont(new Font("Monospaced",Font.PLAIN,14));output.setBackground(new Color(5,25,48));output.setForeground(Theme.AQUA);output.setBorder(new EmptyBorder(12,14,12,14));JScrollPane scroll=new JScrollPane(output);scroll.setMaximumSize(new Dimension(650,170));c.add(scroll);c.add(Box.createVerticalStrut(12));JButton start=Theme.button("Start thread demo",true);c.add(start);start.addActionListener(e->{start.setEnabled(false);output.setText("");new ConcurrencyDemo().start(ConcurrencyDemo.swingLogger(output),()->javax.swing.SwingUtilities.invokeLater(()->start.setEnabled(true)));});JButton producerConsumer=Theme.button("Run producer / consumer",false);c.add(Box.createVerticalStrut(8));c.add(producerConsumer);producerConsumer.addActionListener(e->{output.setText("Starting bounded queue demo with wait() and notifyAll()...\n");producerConsumer.setEnabled(false);new ProducerConsumerDemo().start(ConcurrencyDemo.swingLogger(output),()->javax.swing.SwingUtilities.invokeLater(()->producerConsumer.setEnabled(true)));});back(c);nav("thread-demo",p);}
 private void writePage(){JPanel p=page("Write your message","Let it be honest. The ocean will keep it anonymous.");JPanel c=content(p);c.add(Box.createVerticalStrut(20));JPanel card=Theme.card();card.setLayout(new BorderLayout(10,12));JComboBox<String> category=new JComboBox<>(new String[]{"Unspoken Words","Secret Thoughts","Confessions","Letters to Future Self","Random Thoughts","Things I Never Said"});category.setFont(Theme.BODY);JTextArea area=new JTextArea(7,50);area.setLineWrap(true);area.setWrapStyleWord(true);area.setFont(new Font("Serif",Font.PLAIN,18));area.setForeground(new Color(26,49,72));area.setBackground(new Color(247,252,255));area.setBorder(new EmptyBorder(14,15,14,15));JLabel counter=Theme.label("0 / 1200",13,Theme.MUTED,false);JProgressBar progress=new JProgressBar(0,1200);progress.setPreferredSize(new Dimension(620,7));progress.setBorderPainted(false);progress.setBackground(new Color(225,239,246));progress.setForeground(Theme.AQUA);area.getDocument().addDocumentListener(new javax.swing.event.DocumentListener(){void go(){int length=area.getText().length();counter.setText(length+" / 1200");progress.setValue(Math.min(length,1200));progress.setForeground(length>1100?new Color(255,145,160):Theme.AQUA);}public void insertUpdate(javax.swing.event.DocumentEvent e){go();}public void removeUpdate(javax.swing.event.DocumentEvent e){go();}public void changedUpdate(javax.swing.event.DocumentEvent e){go();}});card.add(category,BorderLayout.NORTH);card.add(new JScrollPane(area),BorderLayout.CENTER);JPanel meter=new JPanel(new BorderLayout(0,6));meter.setOpaque(false);meter.add(counter,BorderLayout.NORTH);meter.add(progress,BorderLayout.SOUTH);card.add(meter,BorderLayout.SOUTH);card.setMaximumSize(new Dimension(680,310));c.add(card);c.add(Box.createVerticalStrut(17));JLabel preview=Theme.label("Your bottle is waiting for its words…",15,Theme.AQUA,false);c.add(preview);area.getDocument().addDocumentListener(new javax.swing.event.DocumentListener(){void go(){String t=area.getText().trim();preview.setText(t.isEmpty()?"Your bottle is waiting for its words…":"◈  “"+(t.length()>90?t.substring(0,90)+"…":t)+"”");}public void insertUpdate(javax.swing.event.DocumentEvent e){go();}public void removeUpdate(javax.swing.event.DocumentEvent e){go();}public void changedUpdate(javax.swing.event.DocumentEvent e){go();}});c.add(Box.createVerticalStrut(12));JButton release=Theme.button("Release Bottle  ↗",true);release.addActionListener(e->{try{String text=ocean.utils.ValidationUtil.validate(area.getText());if(JOptionPane.showConfirmDialog(frame,"Release these words into the ocean? This is anonymous and can't be recalled.","Ready to release",JOptionPane.YES_NO_OPTION,JOptionPane.QUESTION_MESSAGE)==JOptionPane.YES_OPTION){messages.release(text,(String)category.getSelectedItem());JOptionPane.showMessageDialog(frame,"Your words are now floating somewhere in the ocean. ✨","Bon voyage",JOptionPane.INFORMATION_MESSAGE);home();}}catch(Exception ex){error(ex);}});c.add(release);back(c);nav("write",p);}
 private void discover(){JPanel p=page("Choose your drift","Which kind of thought would you like to find?");JPanel c=content(p);c.add(Box.createVerticalStrut(28));JPanel card=Theme.card();card.setLayout(new BoxLayout(card,BoxLayout.Y_AXIS));card.setMaximumSize(new Dimension(440,180));card.add(Theme.label("Filter the ocean",17,Theme.WHITE,true));card.add(Box.createVerticalStrut(14));JComboBox<String> filter=new JComboBox<>(new String[]{"Any category","Unspoken Words","Secret Thoughts","Confessions","Letters to Future Self","Random Thoughts","Things I Never Said"});filter.setFont(Theme.BODY);card.add(filter);c.add(card);c.add(Box.createVerticalStrut(18));JButton begin=Theme.button("Find a bottle  →",true);c.add(begin);begin.addActionListener(e->{discoveryCategory="Any category".equals(filter.getSelectedItem())?null:(String)filter.getSelectedItem();seen.clear();showBottle();});back(c);nav("discover-select",p);}
 private void showBottle(){try{Optional<Bottle> found=bottles.discover(seen,discoveryCategory);JPanel p=page("A bottle found you","A voice from somewhere in the ocean.");JPanel c=content(p);c.add(Box.createVerticalStrut(20));if(found.isEmpty()){JPanel empty=Theme.card();empty.add(Theme.label("The ocean is quiet for now. Release a message to begin.",16,Theme.WHITE,false));c.add(empty);}else{Bottle b=found.get();seen.add(b.getId());JPanel card=Theme.card();card.setLayout(new BoxLayout(card,BoxLayout.Y_AXIS));card.setMaximumSize(new Dimension(630,330));JLabel icon=Theme.label("◈",42,Theme.AQUA,true);icon.setAlignmentX(Component.CENTER_ALIGNMENT);card.add(icon);JTextArea text=new JTextArea(b.getText());text.setEditable(false);text.setLineWrap(true);text.setWrapStyleWord(true);text.setOpaque(false);text.setForeground(Theme.WHITE);text.setFont(new Font("Serif",Font.PLAIN,22));text.setBorder(new EmptyBorder(18,5,18,5));card.add(text);JLabel cat=Theme.label(b.getCategory()+"  ·  adrift since "+b.getCreatedAt().toLocalDate(),13,Theme.MUTED,false);cat.setAlignmentX(Component.CENTER_ALIGNMENT);card.add(cat);c.add(card);}c.add(Box.createVerticalStrut(18));JPanel row=new JPanel(new FlowLayout(FlowLayout.CENTER,12,0));row.setOpaque(false);JButton next=Theme.button("Next bottle  →",true),close=Theme.button("Close bottle",false);next.addActionListener(e->showBottle());close.addActionListener(e->{discoveryCategory=null;home();});row.add(next);row.add(close);c.add(row);c.add(Theme.label("Found this session: "+seen.size(),13,Theme.MUTED,false));back(c);nav("discover"+System.nanoTime(),p);}catch(Exception ex){error(ex);}}
 private void futurePage(){JPanel p=page("A note for later","A letter kept private until the day you choose.");JPanel c=content(p);c.add(Box.createVerticalStrut(12));JTextArea text=new JTextArea(5,48);text.setLineWrap(true);text.setWrapStyleWord(true);text.setFont(new Font("Serif",0,17));text.setBorder(new EmptyBorder(12,14,12,14));text.setMaximumSize(new Dimension(650,170));c.add(new JScrollPane(text));c.add(Box.createVerticalStrut(10));JPanel row=new JPanel(new FlowLayout(FlowLayout.CENTER));row.setOpaque(false);JSpinner date=new JSpinner(new SpinnerDateModel(new Date(),null,null,Calendar.DAY_OF_MONTH));date.setEditor(new JSpinner.DateEditor(date,"yyyy-MM-dd"));row.add(Theme.label("Open on",14,Theme.WHITE,false));row.add(date);JButton save=Theme.button("Seal this letter",true);row.add(save);c.add(row);save.addActionListener(e->{try{Date d=(Date)date.getValue();LocalDate day=d.toInstant().atZone(ZoneId.systemDefault()).toLocalDate();letters.save(text.getText(),day,currentUser.getId());text.setText("");JOptionPane.showMessageDialog(frame,"Your letter is sealed away until "+day+".");futurePage();}catch(Exception ex){error(ex);}});c.add(Box.createVerticalStrut(12));java.util.List<FutureLetter> all;try{all=letters.all(currentUser.getId());}catch(Exception ex){error(ex);all=java.util.List.of();}c.add(Theme.label("Your letters",19,Theme.WHITE,true));JPanel list=new JPanel();list.setOpaque(false);list.setLayout(new BoxLayout(list,BoxLayout.Y_AXIS));for(FutureLetter f:all){JButton item=Theme.button((f.isReady()?"✧ Ready to open  ·  ":"◷ Sealed until  ·  ")+f.getTargetDate(),f.isReady());item.setAlignmentX(Component.CENTER_ALIGNMENT);item.addActionListener(e->{if(f.isReady())JOptionPane.showMessageDialog(frame,f.getText(),"A letter from your past",JOptionPane.PLAIN_MESSAGE);else JOptionPane.showMessageDialog(frame,"This letter is still sealed. Come back on "+f.getTargetDate()+".");});list.add(item);list.add(Box.createVerticalStrut(6));}if(all.isEmpty())list.add(Theme.label("No letters yet. Write one for the person you’re becoming.",14,Theme.MUTED,false));JScrollPane scroll=new JScrollPane(list);scroll.setOpaque(false);scroll.getViewport().setOpaque(false);scroll.setBorder(null);scroll.setPreferredSize(new Dimension(600,180));c.add(scroll);back(c);nav("future",p);}
 private void statistics(){JPanel p=page("The ocean, in numbers","Every bottle is a small act of letting go.");JPanel c=content(p);try{Map<String,Object>s=stats.snapshot(currentUser.getId());JPanel grid=new JPanel(new GridLayout(1,3,14,14));grid.setOpaque(false);grid.add(statCard("Bottles released",s.get("released").toString(),"words set adrift"));grid.add(statCard("Bottles discovered",s.get("discovered").toString(),"times opened by a reader"));grid.add(statCard("Future letters",s.get("letters").toString(),"promises to tomorrow"));c.add(Box.createVerticalStrut(40));c.add(grid);c.add(Box.createVerticalStrut(22));c.add(Theme.label("Messages by category",18,Theme.WHITE,true));Map<?,?>cats=new ReportService().categoryReport();int largest=1;for(Object value:cats.values())largest=Math.max(largest,(Integer)value);for(var en:cats.entrySet())c.add(categoryBar(en.getKey().toString(),(Integer)en.getValue(),largest));JButton export=Theme.button("Export category report as CSV",false);c.add(Box.createVerticalStrut(14));c.add(export);export.addActionListener(e->{JFileChooser chooser=new JFileChooser();chooser.setSelectedFile(new java.io.File("ocean-category-report.csv"));if(chooser.showSaveDialog(frame)==JFileChooser.APPROVE_OPTION){try{new ReportService().exportCategories(chooser.getSelectedFile().toPath());JOptionPane.showMessageDialog(frame,"Category report saved.");}catch(Exception ex){error(ex);}}});}catch(Exception ex){error(ex);}back(c);nav("stats",p);}
 private JPanel categoryBar(String category,int count,int largest){JPanel row=new JPanel(new BorderLayout(14,0));row.setOpaque(false);row.setMaximumSize(new Dimension(650,34));JLabel name=Theme.label(category,14,Theme.WHITE,false);name.setPreferredSize(new Dimension(190,28));JProgressBar bar=new JProgressBar(0,largest);bar.setValue(count);bar.setStringPainted(false);bar.setBorderPainted(false);bar.setBackground(new Color(255,255,255,30));bar.setForeground(Theme.AQUA);JLabel total=Theme.label(Integer.toString(count),14,Theme.MUTED,true);total.setPreferredSize(new Dimension(35,28));row.add(name,BorderLayout.WEST);row.add(bar,BorderLayout.CENTER);row.add(total,BorderLayout.EAST);return row;}
 private JPanel statCard(String title,String n,String caption){JPanel x=Theme.card();x.setLayout(new BoxLayout(x,BoxLayout.Y_AXIS));x.add(Theme.label(title,15,Theme.MUTED,false));x.add(Theme.label(n,36,Theme.AQUA,true));x.add(Theme.label(caption,13,Theme.MUTED,false));return x;}
 private void about(){JPanel p=page("A small ocean for big feelings","A creative place for words without an address.");JPanel c=content(p);c.add(Box.createVerticalStrut(40));JPanel card=Theme.card();card.setLayout(new BoxLayout(card,BoxLayout.Y_AXIS));card.setMaximumSize(new Dimension(650,260));card.add(Theme.label("Not every thought needs an audience.",21,Theme.WHITE,true));card.add(Box.createVerticalStrut(12));JTextArea q=new JTextArea("Not every thought needs an audience. Not every feeling needs an answer. Sometimes, all we need is to let our words float away.");q.setLineWrap(true);q.setWrapStyleWord(true);q.setEditable(false);q.setOpaque(false);q.setForeground(Theme.AQUA);q.setFont(new Font("Serif",Font.ITALIC,22));card.add(q);card.add(Box.createVerticalStrut(16));JTextArea desc=new JTextArea("Write anonymously, release a bottle, and discover a stranger’s words. Local accounts keep future letters private; public bottles are never linked to an account. There are no likes or replies—just the gentle surprise of human connection.");desc.setLineWrap(true);desc.setWrapStyleWord(true);desc.setEditable(false);desc.setOpaque(false);desc.setForeground(Theme.MUTED);desc.setFont(Theme.BODY);card.add(desc);c.add(card);back(c);nav("about",p);}
 private void error(Exception e){String m=e instanceof SQLException?"The ocean database could not be reached. Please try again.":e.getMessage();JOptionPane.showMessageDialog(frame,m,"A little tide trouble",JOptionPane.ERROR_MESSAGE);}
}
